508:   // ---------- simulation ----------
509:   function levelVal(def, field, level) {
510:     const arr = def[field];
511:     if (Array.isArray(arr)) return arr[Math.min(level, arr.length - 1)] || 0;
512:     return arr || 0;
513:   }
514:   function zoneArtKind(def) {
515:     return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i';
516:   }
517:   function bCenter(b) { return { x: b.x + b.w / 2, y: b.y + b.h / 2 }; }
518:   function distance(a, b) {
519:     const ca = bCenter(a), cb = bCenter(b);
520:     return Math.hypot(ca.x - cb.x, ca.y - cb.y);
521:   }
522:   function nearbyArt(b, arts, radiusOverride) {
523:     for (const o of state.buildings) {
524:       if (o === b) continue;
525:       const d = defOf(o);
526:       if (!d) continue;
527:       const art = KK.render.artFor(d, o.level);
528:       if (!arts.includes(art)) continue;
529:       const r = radiusOverride || d.radius || 0;
530:       if (distance(b, o) <= r) return true;
531:     }
532:     return false;
533:   }
534: 
535:   function recalc() {
536:     if (!state) return;
537:     let pop = 0, workers = 0, jobs = 0, cJobs = 0, iJobs = 0;
538:     let powerUse = 0, powerCap = 0, waterUse = 0, waterCap = 0, expense = 0;
539:     let roadCount = 0, zoneCount = 0, houses = 0, shops = 0, factories = 0;
540:     let hasPower = false, hasWater = false, hasPark = false, hasSchool = false, hasStadium = false;
541:     const houseList = [], amenities = [], polluters = [];
542:     for (const b of state.buildings) {
543:       const d = defOf(b); if (!d) continue;
544:       expense += d.maint || 0;
545:       if (d.kind === 'zone-r') {
546:         zoneCount++;
547:         if (b.level > 0) {
548:           pop += levelVal(d, 'cap', b.level);
549:           powerUse += levelVal(d, 'powerUse', b.level);
550:           waterUse += levelVal(d, 'waterUse', b.level);
551:           houseList.push(b); houses++;
552:         }
553:       } else if (d.kind === 'zone-c') {
554:         zoneCount++;
555:         if (b.level > 0) {
556:           cJobs += levelVal(d, 'jobs', b.level);
557:           powerUse += levelVal(d, 'powerUse', b.level);
558:           waterUse += levelVal(d, 'waterUse', b.level);
559:           shops++;
560:         }
561:       } else if (d.kind === 'zone-i') {
562:         zoneCount++;
563:         if (b.level > 0) {
564:           iJobs += levelVal(d, 'jobs', b.level);
565:           powerUse += levelVal(d, 'powerUse', b.level);
566:           waterUse += levelVal(d, 'waterUse', b.level);
567:           factories++;
568:           polluters.push(b);
569:         }
570:       } else {
571:         powerUse += d.powerUse || 0;
572:         waterUse += d.waterUse || 0;
573:         powerCap += d.powerSupply || 0;
574:         waterCap += d.waterSupply || 0;
575:         jobs += d.jobs || 0;
576:         if (d.powerSupply) hasPower = true;
577:         if (d.waterSupply) hasWater = true;
578:         if (artOr(defOf(b), b) === 'park' || artOr(defOf(b), b) === 'smallpark') hasPark = true;
579:         if (artOr(defOf(b), b) === 'school') hasSchool = true;
580:         if (artOr(defOf(b), b) === 'stadium') hasStadium = true;
581:       }
582:       if (d.happy && d.radius) amenities.push(b);
583:       if (b.defId === 'solar') hasPower = true;
584:     }
585:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) roadCount++;
586:     expense += roadCount * DEFS.road.maint;
587:     for (const pid in state.policies) {
588:       const p = KK.POLICIES.find(x => x.id === pid);
589:       if (p && state.policies[pid]) expense += p.cost;
590:     }
591:     workers = Math.round(pop * .42);
592:     jobs += cJobs + iJobs;
593:     const powered = powerUse <= powerCap;
594:     const watered = waterUse <= waterCap;
595:     const policyHappy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? p.happiness : 0), 0);
596:     const commerceBonus = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.commerce || 0) : 0), 0);
597:     const taxPenalty = Math.max(0, (state.taxRate || 9) - 10) * 2.5;
598:     const unemployment = workers > jobs ? Math.min(24, (workers - jobs) / Math.max(1, workers) * 30) : 0;
599:     const pollutionPolicy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.pollution || 0) : 0), 0);
600:     let happyTotal = 0;
601:     for (const h of houseList) {
602:       let bonus = 0;
603:       for (const a of amenities) {
604:         const ad = defOf(a);
605:         if (distance(h, a) <= (ad.radius || 0)) bonus += ad.happy || 0;
606:       }
607:       bonus = Math.min(26, bonus);
608:       let poll = 0;
609:       for (const f of polluters) {
610:         if (distance(h, f) <= (defOf(f).pollutionRadius || 3)) poll += 1.6 + f.level * .5;
611:       }
612:       poll = Math.max(0, Math.min(14, poll) - pollutionPolicy);
613:       let hv = 56 + bonus + policyHappy + state.moodBoost - taxPenalty - unemployment - poll;
614:       if (!powered) hv -= 24;
615:       if (!watered) hv -= 20;
616:       happyTotal += clamp(hv, 0, 100);
617:     }
618:     let happiness;
619:     if (houseList.length) happiness = happyTotal / houseList.length;
620:     else happiness = clamp(62 + policyHappy + state.moodBoost - taxPenalty, 0, 100);
621:     const income = pop * .33 * ((state.taxRate || 9) / 9) + cJobs * .5 * (1 + commerceBonus) + iJobs * .36;
622:     state.population = pop;
623:     state.workers = workers;
624:     state.jobs = jobs;
625:     state.commercialJobs = cJobs;
626:     state.industrialJobs = iJobs;
627:     state.powerUse = Math.round(powerUse * 10) / 10;
628:     state.powerCap = powerCap;
629:     state.waterUse = Math.round(waterUse * 10) / 10;
630:     state.waterCap = waterCap;
631:     state.powered = powered;
632:     state.watered = watered;
633:     state.expense = Math.round(expense * 10) / 10;
634:     state.income = Math.round(income * 10) / 10;
635:     state.net = Math.round((income - expense) * 10) / 10;
636:     state.happiness = Math.round(happiness);
637:     state.roadCount = roadCount;
638:     state.zoneCount = zoneCount;
639:     state.hasPower = hasPower;
640:     state.hasWater = hasWater;
641:     state.hasPark = hasPark;
642:     state.hasSchool = hasSchool;
643:     state.hasStadium = hasStadium;
644:     state.houses = houses; state.shops = shops; state.factories = factories;
645:     state.demandR = clamp(16 + jobs * 1.25 - pop * .38 + (state.happiness < 48 ? -8 : 0), 0, 100);
646:     state.demandC = clamp(8 + pop * .34 - cJobs * .85, 0, 100);
647:     state.demandI = clamp(5 + pop * .18 - iJobs * .45, 0, 100);
648:     state.maxPop = Math.max(state.maxPop, pop);
649:     // economy is deliberately forgiving: never below -2.000
650:     if (state.money < -2000) state.money = -2000;
651:     if (!state.stats) state.stats = {};
652:     state.stats.houses = houses; state.stats.shops = shops; state.stats.factories = factories;
653:   }
654:   function artOr(def, b) { return KK.render.artFor(def, b.level); }
655:   function demandFor(kind) {
656:     return kind === 'r' ? state.demandR : kind === 'c' ? state.demandC : state.demandI;
657:   }
