535:   function drawCar(ctx, car, time) {
536:     // Simulation coordinates already point to the center of the current road tile.
537:     const p = iso(car.x, car.y);
538:     const color = car.color || '#e6563d';
539:     const dir = car.dir || 'x';
540:     const dxs = dir === 'x' ? 1 : dir === '-x' ? -1 : 0;
541:     const dys = dir === 'y' ? 1 : dir === '-y' ? -1 : 0;
542:     const vx = (dxs - dys) * IX, vy = (dxs + dys) * IY;
543:     const length = Math.hypot(vx, vy) || 1;
544:     // Opposing traffic uses opposite sides of the road, leaving room to pass.
545:     const lane = 4.8;
546:     const ang = Math.atan2(vy, vx);
547:     ctx.save();
548:     ctx.translate(p.x - vy / length * lane, p.y + vx / length * lane);
549:     ctx.fillStyle = 'rgba(20,45,30,.24)';
550:     ctx.beginPath(); ctx.ellipse(0, 2, car.type === 'bus' || car.type === 'truck' ? 15 : 11, 5, ang, 0, Math.PI * 2); ctx.fill();
551:     ctx.rotate(ang + Math.PI);
552: 
553:     if (car.type === 'motorcycle') {
554:       // Compact bike with two visible wheels and a helmeted rider.
555:       ctx.fillStyle = '#26323a';
556:       ctx.beginPath(); ctx.arc(-5, 1, 2.7, 0, Math.PI * 2); ctx.fill();
557:       ctx.beginPath(); ctx.arc(5, 1, 2.7, 0, Math.PI * 2); ctx.fill();
558:       line(ctx, { x: -5, y: 1 }, { x: -1, y: -1 }, '#d8dce0', 1.4);
559:       line(ctx, { x: -1, y: -1 }, { x: 2, y: 1 }, '#d8dce0', 1.4);
560:       line(ctx, { x: 2, y: 1 }, { x: 5, y: 1 }, '#d8dce0', 1.4);
561:       ctx.fillStyle = shade(color, .72);
562:       roundRect(ctx, -2.7, -.5, 5.2, 2, 1); ctx.fill();
563:       line(ctx, { x: -1.5, y: -1 }, { x: 2, y: -2.3 }, '#313c43', 2.2);
564:       ctx.fillStyle = '#344b59';
565:       ctx.beginPath(); ctx.ellipse(-.2, -3, 2, 2.8, -.3, 0, Math.PI * 2); ctx.fill();
566:       ctx.fillStyle = '#f2c99a';
567:       ctx.beginPath(); ctx.arc(-2.2, -5.3, 1.55, 0, Math.PI * 2); ctx.fill();
568:       ctx.fillStyle = color;
569:       ctx.beginPath(); ctx.arc(-2.2, -5.8, 1.7, Math.PI, Math.PI * 2); ctx.fill();
570:       ctx.fillStyle = '#fff0bd'; ctx.beginPath(); ctx.arc(-6.3, .2, .8, 0, Math.PI * 2); ctx.fill();
571:       ctx.restore();
572:       return;
573:     }
574: 
575:     if (car.type === 'bus') {
576:       ctx.fillStyle = '#26323a';
577:       for (const x of [-9, 0, 9]) {
578:         roundRect(ctx, x - 2, -5.4, 4, 2.5, 1); ctx.fill();
579:         roundRect(ctx, x - 2, 3, 4, 2.5, 1); ctx.fill();
580:       }
581:       ctx.fillStyle = shade(color, .62);
582:       roundRect(ctx, -15, -4.7, 30, 9.5, 2); ctx.fill();
583:       ctx.fillStyle = color;
584:       roundRect(ctx, -14.5, -4.5, 28.5, 7.7, 1.8); ctx.fill();
