591:       line(ctx, { x: 10, y: -3.5 }, { x: 10, y: 3.2 }, 'rgba(255,255,255,.55)', .7);
592:       ctx.fillStyle = '#fff0bd'; ctx.fillRect(-15, -2.2, 1.1, 1.2); ctx.fillRect(-15, 1, 1.1, 1.2);
593:       ctx.fillStyle = '#c94c43'; ctx.fillRect(14, -2.2, 1, 1); ctx.fillRect(14, 1, 1, 1);
594:       ctx.restore();
