667:   function drawPlacementCandidates(ctx, candidates, bounds, time) {
668:     const pulse = .9 + Math.sin(time * 3.2) * .1;
669:     ctx.save();
670:     ctx.globalAlpha = pulse;
671:     for (const candidate of candidates) {
672:       const p = iso(candidate.x + candidate.w / 2, candidate.y + candidate.h / 2);
673:       if (p.x < bounds.left - 100 || p.x > bounds.right + 100 ||
674:           p.y < bounds.top - 100 || p.y > bounds.bottom + 100) continue;
675:       poly(ctx, diamondPoints(candidate.x, candidate.y, candidate.w, candidate.h, .09),
676:         'rgba(57,214,157,.16)', 'rgba(29,190,133,.78)', 1.5);
677:     }
678:     ctx.restore();
679:   }
