145:   function rng(seed) {
146:     let a = seed >>> 0;
147:     return function () {
148:       a |= 0; a = a + 0x6D2B79F5 | 0;
149:       let t = Math.imul(a ^ a >>> 15, 1 | a);
150:       t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
151:       return ((t ^ t >>> 14) >>> 0) / 4294967296;
152:     };
153:   }
