189:         expected.ids.some((id, i) => current.ids[i] !== id)) {
190:       state.dailyChallenges = expected;
191:     } else {
192:       state.dailyChallenges.progress = current.progress && typeof current.progress === 'object' ? current.progress : {};
193:       state.dailyChallenges.claimed = current.claimed && typeof current.claimed === 'object' ? current.claimed : {};
