198:   function generateMap(seed) {
199:     const rand = rng(seed || Date.now());
200:     const grid = [];
201:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
202:       grid.push({ terrain: 'grass', road: false, b: null });
203:     }
204:     const s = { grid };
205:     // main lake (lower-left of map)
206:     const lx = 18.2, ly = 17.4, lr = 2.9;
207:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
208:       const d = Math.hypot(x - lx, (y - ly) * 1.2);
209:       if (d < lr + rand() * .55) grid[idx(x, y)].terrain = 'water';
210:       else if (d < lr + 1.05) grid[idx(x, y)].terrain = Math.random() < .6 ? 'sand' : 'grass';
211:     }
212:     // small pond
213:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
214:       const d = Math.hypot(x - 3.6, (y - 20.2) * 1.15);
215:       if (d < 1.5 + rand() * .3) grid[idx(x, y)].terrain = 'water';
216:       else if (d < 2.1) grid[idx(x, y)].terrain = 'sand';
217:     }
218:     // scatter nature outside the central clearing
219:     const trees = [];
220:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
221:       const t = grid[idx(x, y)];
222:       if (t.terrain !== 'grass') continue;
223:       const dc = Math.hypot(x - 12, y - 12);
224:       const edge = Math.min(x, y, GRID - 1 - x, GRID - 1 - y);
225:       let chance = 0;
226:       if (dc > 7.6) chance = .22;
227:       if (edge < 3) chance += .2;
228:       if (dc > 10) chance += .12;
229:       if (rand() < chance) trees.push({ defId: 'tree', x, y, level: 1, variant: Math.floor(rand() * 3) });
230:       else if (rand() < .018 && dc > 6.5) trees.push({ defId: 'rock', x, y, level: 1 });
231:     }
232:     return { grid, treeSeed: trees };
233:   }
