300:     let wild = false;
301:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
302:       const t = state.grid[idx(xx, yy)];
303:       if (t.terrain === 'water') return { ok: false, msg: 'Tidak bisa membangun di atas air.' };
304:       if (t.road) return { ok: false, msg: 'Petak sudah dipakai jalan.' };
305:       if (t.b) {
306:         if (def.kind === 'road') return { ok: false, msg: 'Ada bangunan di petak ini.' };
307:         if (t.b.defId === 'tree' || t.b.defId === 'rock') wild = true;
308:         else return { ok: false, msg: 'Petak sudah terisi.' };
309:       }
310:     }
311:     if (wild) return { ok: false, msg: 'Bersihkan pohon/batu dengan alat bongkar dulu.' };
312:     if (def.kind !== 'road' && def.kind !== 'decor') {
313:       let ok = false;
314:       const test = { x, y, w: def.w, h: def.h };
315:       ok = roadAccess(test);
316:       if (!ok) return { ok: false, msg: 'Butuh akses jalan di sebelahnya.' };
317:     }
318:     if (!opts.free && state.money < def.cost) return { ok: false, msg: 'Kas kota tidak cukup.' };
