396:   // ---------- cars ----------
397:   function allRoads() {
398:     const list = [];
399:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) list.push({ x, y });
400:     return list;
