402:   const CAR_COLORS = ['#e6563d', '#3b8fd4', '#f2c94c', '#4fae62', '#c14b7c', '#f28b3c', '#6b7c8a', '#f7f4ec'];
403:   const VEHICLE_TYPES = ['car', 'car', 'car', 'motorcycle', 'motorcycle', 'bus', 'truck'];
404:   function newCar(tx, ty) {
405:     const choices = [];
406:     for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
407:       const nx = tx + dx, ny = ty + dy;
408:       if (inBounds(nx, ny) && state.grid[idx(nx, ny)].road) choices.push({ x: nx, y: ny, dx, dy });
409:     }
410:     if (!choices.length) return null;
411:     const c = choices[Math.floor(Math.random() * choices.length)];
412:     const type = VEHICLE_TYPES[Math.floor(Math.random() * VEHICLE_TYPES.length)];
413:     const speed = .45 + Math.random() * .35;
414:     return {
415:       x: tx + .5, y: ty + .5, fromX: tx + .5, fromY: ty + .5, toX: c.x + .5, toY: c.y + .5,
416:       t: 0, speed: speed * (type === 'bus' || type === 'truck' ? .78 : type === 'motorcycle' ? 1.12 : 1),
417:       type, color: type === 'bus' ? '#e5b83f' : type === 'truck' ? '#4d9b78' : CAR_COLORS[Math.floor(Math.random() * CAR_COLORS.length)],
418:       dir: c.dx > 0 ? 'x' : c.dx < 0 ? '-x' : c.dy > 0 ? 'y' : '-y', alive: true
419:     };
420:   }
421:   function carShape(car) {
422:     const dx = car.dir === 'x' ? 1 : car.dir === '-x' ? -1 : 0;
423:     const dy = car.dir === 'y' ? 1 : car.dir === '-y' ? -1 : 0;
424:     const vx = (dx - dy) * 32, vy = (dx + dy) * 16;
425:     const length = Math.hypot(vx, vy) || 1;
426:     const ux = vx / length, uy = vy / length;
427:     const px = (car.x - car.y) * 32 - uy * 4.8;
428:     const py = (car.x + car.y) * 16 + ux * 4.8;
429:     const halfLength = car.type === 'bus' || car.type === 'truck' ? 16 : car.type === 'motorcycle' ? 6.5 : 10;
430:     return { x: px, y: py, ux, uy, halfLength, halfWidth: 4.6 };
431:   }
432:   function carsOverlap(a, b) {
433:     const sa = carShape(a), sb = carShape(b);
434:     const axes = [[sa.ux, sa.uy], [-sa.uy, sa.ux], [sb.ux, sb.uy], [-sb.uy, sb.ux]];
435:     for (const [ax, ay] of axes) {
436:       const distance = Math.abs((sb.x - sa.x) * ax + (sb.y - sa.y) * ay);
437:       const ra = sa.halfLength * Math.abs(sa.ux * ax + sa.uy * ay) + sa.halfWidth * Math.abs(-sa.uy * ax + sa.ux * ay);
438:       const rb = sb.halfLength * Math.abs(sb.ux * ax + sb.uy * ay) + sb.halfWidth * Math.abs(-sb.uy * ax + sb.ux * ay);
439:       if (distance >= ra + rb) return false;
440:     }
441:     return true;
442:   }
443:   function nextCarState(car, dt, size, isRoad) {
444:     const next = { ...car };
445:     next.t += dt * next.speed;
446:     if (next.t >= 1) {
447:       const tx = Math.round(next.toX - .5), ty = Math.round(next.toY - .5);
448:       const prevDx = Math.sign(next.toX - next.fromX), prevDy = Math.sign(next.toY - next.fromY);
449:       next.fromX = next.toX; next.fromY = next.toY;
450:       const choices = [];
451:       for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
452:         const nx = tx + dx, ny = ty + dy;
453:         if (nx >= 0 && ny >= 0 && nx < size && ny < size && isRoad(nx, ny)) choices.push({ x: nx, y: ny, dx, dy });
454:       }
455:       if (!choices.length) { next.alive = false; return next; }
456:       const reverse = { dx: -prevDx, dy: -prevDy };
457:       const forward = choices.filter(pick => pick.dx !== reverse.dx || pick.dy !== reverse.dy);
458:       const options = forward.length ? forward : choices;
459:       const pick = options[Math.floor(Math.random() * options.length)];
460:       next.toX = pick.x + .5; next.toY = pick.y + .5;
461:       next.dir = pick.dx > 0 ? 'x' : pick.dx < 0 ? '-x' : pick.dy > 0 ? 'y' : '-y';
462:       next.t = 0;
463:     }
464:     next.x = lerp(next.fromX, next.toX, next.t);
465:     next.y = lerp(next.fromY, next.toY, next.t);
466:     return next;
467:   }
468:   function spawnCars(initial) {
469:     const roads = allRoads();
470:     if (!roads.length) return;
471:     const cap = Math.min(16, Math.floor(roads.length / 2.4));
472:     let attempts = 0;
473:     while (state.cars.length < cap && attempts++ < cap * 24) {
474:       const r = roads[Math.floor(Math.random() * roads.length)];
475:       const c = newCar(r.x, r.y);
476:       if (!c) continue;
477:       c.t = initial ? Math.random() : 0;
478:       c.x = lerp(c.fromX, c.toX, c.t); c.y = lerp(c.fromY, c.toY, c.t);
479:       if (state.cars.some(other => carsOverlap(c, other))) continue;
480:       state.cars.push(c);
481:     }
482:   }
483:   function ensureCars() { spawnCars(); }
484:   function updateCars(dt) {
485:     if (!state || !state.cars) return;
486:     const isRoad = (x, y) => state.grid[idx(x, y)].road;
487:     for (const c of state.cars) {
488:       if (!c.alive) continue;
489:       const next = nextCarState(c, dt, state.gridSize, isRoad);
490:       if (state.cars.some(other => other !== c && carsOverlap(next, other))) continue;
491:       Object.assign(c, next);
492:     }
493:     state.cars = state.cars.filter(c => c.alive);
494:     const roads = allRoads();
495:     if (state.cars.length < Math.min(14, Math.floor(roads.length / 2.4)) && Math.random() < .02) {
496:       const r = roads[Math.floor(Math.random() * roads.length)];
497:       if (r) {
498:         const c = newCar(r.x, r.y);
499:         if (c && !state.cars.some(other => carsOverlap(c, other))) state.cars.push(c);
500:       }
501:     }
502:   }
