531:   function recalc() {
532:     if (!state) return;
533:     let pop = 0, workers = 0, jobs = 0, cJobs = 0, iJobs = 0;
534:     let powerUse = 0, powerCap = 0, waterUse = 0, waterCap = 0, expense = 0;
535:     let roadCount = 0, zoneCount = 0, houses = 0, shops = 0, factories = 0;
536:     let hasPower = false, hasWater = false, hasPark = false, hasSchool = false, hasStadium = false;
537:     const houseList = [], amenities = [], polluters = [];
538:     for (const b of state.buildings) {
539:       const d = defOf(b); if (!d) continue;
540:       expense += d.maint || 0;
541:       if (d.kind === 'zone-r') {
542:         zoneCount++;
543:         if (b.level > 0) {
544:           pop += levelVal(d, 'cap', b.level);
545:           powerUse += levelVal(d, 'powerUse', b.level);
546:           waterUse += levelVal(d, 'waterUse', b.level);
547:           houseList.push(b); houses++;
548:         }
549:       } else if (d.kind === 'zone-c') {
550:         zoneCount++;
551:         if (b.level > 0) {
552:           cJobs += levelVal(d, 'jobs', b.level);
553:           powerUse += levelVal(d, 'powerUse', b.level);
554:           waterUse += levelVal(d, 'waterUse', b.level);
555:           shops++;
556:         }
557:       } else if (d.kind === 'zone-i') {
558:         zoneCount++;
559:         if (b.level > 0) {
560:           iJobs += levelVal(d, 'jobs', b.level);
561:           powerUse += levelVal(d, 'powerUse', b.level);
562:           waterUse += levelVal(d, 'waterUse', b.level);
563:           factories++;
564:           polluters.push(b);
565:         }
566:       } else {
567:         powerUse += d.powerUse || 0;
568:         waterUse += d.waterUse || 0;
569:         powerCap += d.powerSupply || 0;
570:         waterCap += d.waterSupply || 0;
571:         jobs += d.jobs || 0;
572:         if (d.powerSupply) hasPower = true;
573:         if (d.waterSupply) hasWater = true;
574:         if (artOr(defOf(b), b) === 'park' || artOr(defOf(b), b) === 'smallpark') hasPark = true;
575:         if (artOr(defOf(b), b) === 'school') hasSchool = true;
576:         if (artOr(defOf(b), b) === 'stadium') hasStadium = true;
577:       }
578:       if (d.happy && d.radius) amenities.push(b);
579:       if (b.defId === 'solar') hasPower = true;
580:     }
581:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) roadCount++;
582:     expense += roadCount * DEFS.road.maint;
583:     for (const pid in state.policies) {
584:       const p = KK.POLICIES.find(x => x.id === pid);
585:       if (p && state.policies[pid]) expense += p.cost;
586:     }
587:     workers = Math.round(pop * .42);
588:     jobs += cJobs + iJobs;
589:     const powered = powerUse <= powerCap;
590:     const watered = waterUse <= waterCap;
591:     const policyHappy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? p.happiness : 0), 0);
592:     const commerceBonus = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.commerce || 0) : 0), 0);
593:     const taxPenalty = Math.max(0, (state.taxRate || 9) - 10) * 2.5;
594:     const unemployment = workers > jobs ? Math.min(24, (workers - jobs) / Math.max(1, workers) * 30) : 0;
595:     const pollutionPolicy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.pollution || 0) : 0), 0);
596:     let happyTotal = 0;
597:     for (const h of houseList) {
598:       let bonus = 0;
599:       for (const a of amenities) {
600:         const ad = defOf(a);
601:         if (distance(h, a) <= (ad.radius || 0)) bonus += ad.happy || 0;
602:       }
603:       bonus = Math.min(26, bonus);
604:       let poll = 0;
605:       for (const f of polluters) {
606:         if (distance(h, f) <= (defOf(f).pollutionRadius || 3)) poll += 1.6 + f.level * .5;
607:       }
608:       poll = Math.max(0, Math.min(14, poll) - pollutionPolicy);
609:       let hv = 56 + bonus + policyHappy + state.moodBoost - taxPenalty - unemployment - poll;
610:       if (!powered) hv -= 24;
611:       if (!watered) hv -= 20;
612:       happyTotal += clamp(hv, 0, 100);
613:     }
614:     let happiness;
615:     if (houseList.length) happiness = happyTotal / houseList.length;
616:     else happiness = clamp(62 + policyHappy + state.moodBoost - taxPenalty, 0, 100);
617:     const income = pop * .33 * ((state.taxRate || 9) / 9) + cJobs * .5 * (1 + commerceBonus) + iJobs * .36;
618:     state.population = pop;
619:     state.workers = workers;
620:     state.jobs = jobs;
621:     state.commercialJobs = cJobs;
622:     state.industrialJobs = iJobs;
623:     state.powerUse = Math.round(powerUse * 10) / 10;
624:     state.powerCap = powerCap;
625:     state.waterUse = Math.round(waterUse * 10) / 10;
626:     state.waterCap = waterCap;
627:     state.powered = powered;
628:     state.watered = watered;
629:     state.expense = Math.round(dailyAmount(expense) * 10) / 10;
630:     state.income = Math.round(dailyAmount(income) * 10) / 10;
631:     state.net = Math.round((state.income - state.expense) * 10) / 10;
632:     state.happiness = Math.round(happiness);
633:     state.roadCount = roadCount;
634:     state.zoneCount = zoneCount;
635:     state.hasPower = hasPower;
636:     state.hasWater = hasWater;
637:     state.hasPark = hasPark;
638:     state.hasSchool = hasSchool;
639:     state.hasStadium = hasStadium;
640:     state.houses = houses; state.shops = shops; state.factories = factories;
641:     state.demandR = clamp(16 + jobs * 1.25 - pop * .38 + (state.happiness < 48 ? -8 : 0), 0, 100);
642:     state.demandC = clamp(8 + pop * .34 - cJobs * .85, 0, 100);
643:     state.demandI = clamp(5 + pop * .18 - iJobs * .45, 0, 100);
644:     state.maxPop = Math.max(state.maxPop, pop);
645:     // economy is deliberately forgiving: never below -2.000
646:     if (state.money < -2000) state.money = -2000;
647:     if (!state.stats) state.stats = {};
648:     state.stats.houses = houses; state.stats.shops = shops; state.stats.factories = factories;
649:   }
650:   function artOr(def, b) { return KK.render.artFor(def, b.level); }
651:   function demandFor(kind) {
652:     return kind === 'r' ? state.demandR : kind === 'c' ? state.demandC : state.demandI;
653:   }
654: 
655:   function simulateTick() {
656:     if (!state) return;
657:     state.tick++;
658:     const dayStep = BASE_TICK_SECONDS / DAY_SECONDS;
659:     const scale = dayStep;
660:     state.elapsedDays = (state.elapsedDays || 0) + dayStep;
661:     state.hour = (state.hour + 24 * dayStep) % 24;
662:     state.moodBoost *= Math.pow(.966, scale);
663:     if (Math.abs(state.moodBoost) < .05) state.moodBoost = 0;
664:     recalc();
665:     const hasPower = state.powerCap >= state.powerUse;
666:     const hasWater = state.waterCap >= state.waterUse;
667:     let changed = false;
668:     for (const b of state.buildings.slice()) {
669:       const d = defOf(b);
670:       if (!d || !d.kind || !d.kind.startsWith('zone')) continue;
671:       const ok = hasPower && hasWater && roadAccess(b);
672:       if (b.level === 0) {
673:         const kind = zoneArtKind(d);
674:         if (ok && demandFor(kind) > 0 && state.happiness >= 38) {
675:           b.growth += (1 + (state.happiness > 66 ? .5 : 0)) * scale;
676:           if (b.growth >= 2) { b.level = 1; b.growth = 0; b.evo = 0; changed = true; }
677:         } else b.growth = Math.max(0, b.growth - .5 * scale);
678:       } else {
679:         const school = nearbyArt(b, ['school']);
680:         const hospital = nearbyArt(b, ['hospital']);
681:         let maxLv = 3;
682:         if (kindOf(d) === 'r') maxLv = 2 + (school ? 1 : 0) + (hospital ? 1 : 0);
683:         if (b.level < Math.min(d.maxLevel || 3, maxLv) && ok && state.happiness >= 50) {
684:           b.evo += (state.happiness >= 68 ? 2 : 1) * scale;
685:           const need = [0, 7, 13, 21][b.level] || 99;
686:           if (b.evo >= need) { b.level++; b.evo = 0; changed = true; }
687:         } else if (b.evo > 0) b.evo = Math.max(0, b.evo - scale);
688:       }
689:     }
690:     if (changed) recalc();
691:     state.money += state.net * dayStep;
692:     // resource warnings
693:     if (!state.warned.power && state.powerUse > state.powerCap && state.powerUse > 0) {
694:       toast('Listrik tidak cukup! Bangun pembangkit atau taman surya.', 'bad', 'bolt');
695:       state.warned.power = true;
696:     }
697:     if (state.powerUse <= state.powerCap) state.warned.power = false;
698:     if (!state.warned.water && state.waterUse > state.waterCap && state.waterUse > 0) {
699:       toast('Pasokan air kurang! Bangun menara air tambahan.', 'bad', 'drop');
700:       state.warned.water = true;
701:     }
702:     if (state.waterUse <= state.waterCap) state.warned.water = false;
703:     checkUnlocks();
704:     checkMissions();
705:     // random city event
706:     state.eventTimer = (state.eventTimer || 48) - scale;
707:     if (state.eventTimer <= 0) {
708:       state.eventTimer = 55 + Math.floor(Math.random() * 25);
709:       if (!state.modalPause && state.population >= 20) setTimeout(showRandomEvent, 350);
710:     }
711:     if (state.tick % Math.max(1, Math.round(2 / scale)) === 0) spawnCars();
712:     if (state.tick % Math.max(1, Math.round(20 / scale)) === 0) saveGame(true);
713:     updateAll();
714:     updateSelection();
715:   }
716:   function kindOf(def) { return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i'; }
717: 
718:   function checkUnlocks(silent) {
719:     if (!state) return;
720:     for (const id in DEFS) {
721:       const d = DEFS[id];
722:       if (!d.unlockPop || d.unlockPop > state.maxPop) continue;
723:       if (!state.unlocked[id]) {
724:         state.unlocked[id] = true;
725:         if (!silent) {
726:           toast(`Bangunan baru terbuka: ${d.name}`, 'reward', 'trophy');
727:           sfx.unlock();
