1413:   function drawTreeAt(ctx, gx, gy, scale, variant, time) {
1414:     const s = scale || 1;
1415:     const c = iso(gx, gy);
1416:     const sway = Math.sin(time * 1.25 + gx * .7 + gy * .4) * .8 * s;
1417:     ellipse(ctx, c.x + 2, c.y + 1, 13 * s, 5.5 * s, 'rgba(25,60,35,.18)');
1418:     line(ctx, { x: c.x, y: c.y + 1 }, { x: c.x + sway * .4, y: c.y - 13 * s }, '#7a5534', 2.4 * s);
1419:     const v = variant == null ? 0 : variant;
1420:     if (v === 1) {
1421:       // pine
1422:       for (let i = 0; i < 3; i++) {
1423:         const yy = c.y - (10 + i * 7) * s;
1424:         const w = (16 - i * 4) * s;
1425:         poly(ctx, [{ x: c.x + sway, y: yy - 14 * s }, { x: c.x + w, y: yy + 4 * s }, { x: c.x - w, y: yy + 4 * s }], i === 0 ? '#3f7d4b' : i === 1 ? '#488b52' : '#559a5d');
1426:       }
1427:     } else if (v === 2) {
1428:       // palm
1429:       for (let i = 0; i < 6; i++) {
1430:         const a = -Math.PI / 2 + (i - 2.5) * .52;
1431:         const ex = c.x + Math.cos(a) * 20 * s + sway, ey = c.y - 22 * s + Math.sin(a) * 10 * s;
1432:         line(ctx, { x: c.x + sway, y: c.y - 20 * s }, { x: ex, y: ey }, '#3f8b52', 2.4 * s);
1433:         line(ctx, { x: ex, y: ey }, { x: ex + Math.cos(a) * 6 * s, y: ey + 3 * s }, '#4c9e5f', 1.6 * s);
1434:       }
1435:       ctx.fillStyle = '#8a5a34'; ctx.beginPath(); ctx.arc(c.x + sway, c.y - 20 * s, 2.4 * s, 0, 7); ctx.fill();
1436:     } else {
1437:       const blobs = [[0, -24, 11], [-8, -19, 8], [8, -19, 8], [2, -31, 8]];
1438:       for (const [bx, by, br] of blobs) {
1439:         ctx.fillStyle = br > 9 ? '#428a4d' : '#4e9d58';
1440:         ctx.beginPath(); ctx.arc(c.x + bx * s + sway, c.y + by * s, br * s, 0, 7); ctx.fill();
1441:       }
1442:       ctx.fillStyle = 'rgba(140,220,130,.28)';
1443:       ctx.beginPath(); ctx.arc(c.x - 5 * s + sway, c.y - 27 * s, 5 * s, 0, 7); ctx.fill();
1444:     }
1445:   }
