289:       if (inBounds(x - 1, y) && state.grid[idx(x - 1, y)].road) return true;
290:       if (inBounds(x + 1, y) && state.grid[idx(x + 1, y)].road) return true;
291:       if (inBounds(x, y - 1) && state.grid[idx(x, y - 1)].road) return true;
292:       if (inBounds(x, y + 1) && state.grid[idx(x, y + 1)].road) return true;
