302:       const t = state.grid[idx(xx, yy)];
303:       if (t.terrain === 'water') return { ok: false, msg: 'Tidak bisa membangun di atas air.' };
304:       if (t.road) return { ok: false, msg: 'Petak sudah dipakai jalan.' };
305:       if (t.b) {
