1023:   function updateMinimap() {
1024:     const cv = $('#minimap'); if (!cv || !state) return;
1025:     const c = cv.getContext('2d');
1026:     const w = cv.width, h = cv.height;
1027:     c.clearRect(0, 0, w, h);
1028:     c.fillStyle = '#8ccfe0'; c.fillRect(0, 0, w, h);
1029:     const size = state.gridSize;
1030:     const padX = (w - (Math.min(w, h) - 16)) / 2 + 8;
1031:     const padY = (h - (Math.min(w, h) - 16)) / 2 + 8;
1032:     const cell = (Math.min(w, h) - 16) / size;
1033:     for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
1034:       const t = state.grid[idx(x, y)];
1035:       let col = t.terrain === 'water' ? '#3b93b3' : t.terrain === 'sand' ? '#e6d29c' : '#87c568';
1036:       if (t.road) col = '#59626a';
1037:       if (t.b) {
1038:         const d = defOf(t.b);
1039:         if (d.kind === 'zone-r') col = '#3aa96b';
1040:         else if (d.kind === 'zone-c') col = '#3b8fd4';
1041:         else if (d.kind === 'zone-i') col = '#d9a03c';
1042:         else if (d.cat === 'service') col = '#e05a8b';
1043:         else if (d.cat === 'fun') col = '#f0a33e';
1044:         else if (d.kind === 'decor') col = t.b.defId === 'tree' ? '#4f9b54' : '#7bc46a';
1045:         else col = '#6f8f89';
1046:       }
1047:       c.fillStyle = col;
1048:       c.fillRect(padX + x * cell, padY + y * cell, Math.ceil(cell), Math.ceil(cell));
1049:     }
1050:     // camera marker (approx)
1051:     const gx = (cam.x / 32 + cam.y / 16) / 2;
1052:     const gy = (cam.y / 16 - cam.x / 32) / 2;
1053:     c.strokeStyle = 'rgba(255,255,255,.95)'; c.lineWidth = 2;
1054:     c.strokeRect(padX + gx * cell - 8, padY + gy * cell - 8, 16, 16);
