717:     const T = { x: g.T.x, y: g.T.y - height }, R = { x: g.R.x, y: g.R.y - height }, B = { x: g.B.x, y: g.B.y - height }, L = { x: g.L.x, y: g.L.y - height };
718:     const cx = (T.x + B.x) / 2, cy = (T.y + B.y) / 2;
719:     const inset = p => ({ x: lerp(p.x, cx, .07), y: lerp(p.y, cy, .07) });
720:     const iT = inset(T), iR = inset(R), iB = inset(B), iL = inset(L);
721:     poly(ctx, [T, R, iR, iT], color); poly(ctx, [R, B, iB, iR], shade(color, .82));
722:     poly(ctx, [B, L, iL, iB], shade(color, .75)); poly(ctx, [L, T, iT, iL], shade(color, .92));
723:   }
724:   function cylinder(ctx, cx, baseY, rx, h, color) {
725:     const topY = baseY - h;
726:     const grd = ctx.createLinearGradient(cx - rx, 0, cx + rx, 0);
727:     grd.addColorStop(0, shade(color, .78));
728:     grd.addColorStop(.45, light(color, .12));
729:     grd.addColorStop(1, shade(color, .66));
730:     ctx.fillStyle = grd;
731:     ctx.beginPath(); ctx.moveTo(cx - rx, topY); ctx.lineTo(cx - rx, baseY); ctx.ellipse(cx, baseY, rx, rx * .42, 0, Math.PI, 0, true); ctx.lineTo(cx + rx, topY); ctx.closePath(); ctx.fill();
732:     ellipse(ctx, cx, topY, rx, rx * .42, light(color, .17), shade(color, .58), .7);
733:   }
734:   function smoke(ctx, cx, cy, time, scale) {
735:     const sc = scale || 1;
736:     for (let i = 0; i < 4; i++) {
737:       const t = (time * .19 + i * .25) % 1;
738:       const r = (4 + t * 12) * sc;
739:       ctx.globalAlpha = (1 - t) * .3;
740:       ctx.fillStyle = i % 2 ? '#e9f0ef' : '#d8e0df';
741:       ctx.beginPath(); ctx.arc(cx + Math.sin(time * .5 + i * 2.1) * 5 * sc, cy - t * 46 * sc, r, 0, 7); ctx.fill();
742:     }
743:     ctx.globalAlpha = 1;
744:   }
745:   function flag(ctx, x, y, h, time) {
746:     line(ctx, { x, y }, { x, y: y - h }, '#8b8f8b', 1.6);
747:     const wave = Math.sin(time * 2.4 + x * .1) * 1.8;
748:     poly(ctx, [{ x: x + 1, y: y - h }, { x: x + 1 + 11, y: y - h + 1 + wave }, { x: x + 1 + 11, y: y - h + 5 + wave }, { x: x + 1, y: y - h + 4 }], '#e0453a');
749:     poly(ctx, [{ x: x + 1, y: y - h + 4 }, { x: x + 1 + 11, y: y - h + 5 + wave }, { x: x + 1 + 11, y: y - h + 8 + wave }, { x: x + 1, y: y - h + 7 }], '#f7f4ec');
750:   }
751:   function basePad(ctx, b, color1, color2) {
752:     const p = diamondPoints(b.x, b.y, b.w, b.h, .015);
753:     poly(ctx, p, color1 || '#d9d0ba');
754:     const p2 = diamondPoints(b.x, b.y, b.w, b.h, .08);
755:     poly(ctx, p2, color2 || light(color1 || '#d9d0ba', .12));
