655:   function simulateTick() {
656:     if (!state) return;
657:     state.tick++;
658:     const dayStep = BASE_TICK_SECONDS / DAY_SECONDS;
659:     const scale = dayStep;
660:     state.elapsedDays = (state.elapsedDays || 0) + dayStep;
661:     state.hour = (state.hour + 24 * dayStep) % 24;
662:     state.moodBoost *= Math.pow(.966, scale);
663:     if (Math.abs(state.moodBoost) < .05) state.moodBoost = 0;
664:     recalc();
665:     const hasPower = state.powerCap >= state.powerUse;
666:     const hasWater = state.waterCap >= state.waterUse;
667:     let changed = false;
668:     for (const b of state.buildings.slice()) {
669:       const d = defOf(b);
670:       if (!d || !d.kind || !d.kind.startsWith('zone')) continue;
671:       const ok = hasPower && hasWater && roadAccess(b);
672:       if (b.level === 0) {
673:         const kind = zoneArtKind(d);
674:         if (ok && demandFor(kind) > 0 && state.happiness >= 38) {
675:           b.growth += (1 + (state.happiness > 66 ? .5 : 0)) * scale;
676:           if (b.growth >= 2) { b.level = 1; b.growth = 0; b.evo = 0; changed = true; }
677:         } else b.growth = Math.max(0, b.growth - .5 * scale);
678:       } else {
679:         const school = nearbyArt(b, ['school']);
680:         const hospital = nearbyArt(b, ['hospital']);
681:         let maxLv = 3;
682:         if (kindOf(d) === 'r') maxLv = 2 + (school ? 1 : 0) + (hospital ? 1 : 0);
683:         if (b.level < Math.min(d.maxLevel || 3, maxLv) && ok && state.happiness >= 50) {
684:           b.evo += (state.happiness >= 68 ? 2 : 1) * scale;
685:           const need = [0, 7, 13, 21][b.level] || 99;
686:           if (b.evo >= need) { b.level++; b.evo = 0; changed = true; }
687:         } else if (b.evo > 0) b.evo = Math.max(0, b.evo - scale);
688:       }
689:     }
690:     if (changed) recalc();
691:     state.money += state.net * dayStep;
692:     // resource warnings
693:     if (!state.warned.power && state.powerUse > state.powerCap && state.powerUse > 0) {
