504:   // ---------- simulation ----------
505:   function levelVal(def, field, level) {
506:     const arr = def[field];
507:     if (Array.isArray(arr)) return arr[Math.min(level, arr.length - 1)] || 0;
508:     return arr || 0;
509:   }
510:   function zoneArtKind(def) {
511:     return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i';
512:   }
513:   function bCenter(b) { return { x: b.x + b.w / 2, y: b.y + b.h / 2 }; }
514:   function distance(a, b) {
515:     const ca = bCenter(a), cb = bCenter(b);
516:     return Math.hypot(ca.x - cb.x, ca.y - cb.y);
517:   }
518:   function nearbyArt(b, arts, radiusOverride) {
519:     for (const o of state.buildings) {
520:       if (o === b) continue;
521:       const d = defOf(o);
522:       if (!d) continue;
523:       const art = KK.render.artFor(d, o.level);
524:       if (!arts.includes(art)) continue;
525:       const r = radiusOverride || d.radius || 0;
526:       if (distance(b, o) <= r) return true;
527:     }
528:     return false;
529:   }
