974:           <div class="daily-challenge-desc">${challenge.desc}</div>
975:           <div class="daily-progress" role="progressbar" aria-label="${challenge.title}" aria-valuemin="0" aria-valuemax="${challenge.target}" aria-valuenow="${progress}"><span style="width:${Math.round(progress / challenge.target * 100)}%"></span></div>
