1231:   function drawFountainAt(ctx, gx, gy, scale, time) {
1232:     const c = iso(gx, gy);
1233:     const s = scale || 1;
1234:     ellipse(ctx, c.x, c.y, 15 * s, 7.5 * s, '#9b9587', '#c4bda9', 1);
1235:     ellipse(ctx, c.x, c.y, 11 * s, 5.3 * s, '#3ba1c4', '#7fd3e4', .8);
1236:     ellipse(ctx, c.x, c.y - 2 * s, 4 * s, 2 * s, '#6fc4d9');
1237:     // spray
1238:     const h = 18 * s;
1239:     ctx.strokeStyle = 'rgba(225,250,255,.65)'; ctx.lineWidth = 1;
1240:     for (let i = -2; i <= 2; i++) {
1241:       ctx.beginPath();
1242:       ctx.moveTo(c.x + i * 3 * s, c.y - 3 * s);
1243:       ctx.quadraticCurveTo(c.x + i * 5 * s, c.y - h * .7, c.x + i * 1.5 * s, c.y - 2 * s);
1244:       ctx.stroke();
1245:     }
1246:     ctx.strokeStyle = 'rgba(225,250,255,.9)'; ctx.lineWidth = 1.4;
1247:     line(ctx, { x: c.x, y: c.y - 4 * s }, { x: c.x, y: c.y - h }, 'rgba(235,255,255,.9)', 1.6);
1248:     const drop = (time * .35) % 1;
1249:     for (let i = 0; i < 3; i++) {
1250:       const t = (drop + i / 3) % 1;
1251:       ctx.globalAlpha = .55; ctx.fillStyle = '#dffbff';
1252:       ctx.beginPath(); ctx.arc(c.x + Math.sin(t * 7 + i) * 4 * s, c.y - 5 * s - t * h, 1.2, 0, 7); ctx.fill();
1253:       ctx.globalAlpha = 1;
1254:     }
1255:     // center bowl
1256:     ellipse(ctx, c.x, c.y - 4 * s, 3.4 * s, 1.6 * s, '#a7c7c4');
1257:   }
